-- Droop account and preset tables. Run once in Supabase SQL Editor.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, display_name text, plan text not null default 'free' check (plan in ('free','pro')), updated_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,email) values (new.id,new.email) on conflict (id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; drop policy if exists "profiles own row" on public.profiles; create policy "profiles own row" on public.profiles for select using (auth.uid()=id); drop policy if exists "profiles own update" on public.profiles; create policy "profiles own update" on public.profiles for update using (auth.uid()=id) with check (auth.uid()=id);
create table if not exists public.presets (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, tool_slug text not null, name text not null, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.presets enable row level security; drop policy if exists "presets own rows" on public.presets; create policy "presets own rows" on public.presets for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
